-- 1131: Blog post — "AZ-400 DevOps Engineer Expert in Singapore: Exam Domains, Funding and Practice Exams"
--
--       Lead-in post for WSQ - Designing and Implementing Microsoft DevOps Solutions (AZ-400) (TGS-2024042605).
--       Backdated to 2025-10-14 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $2,000.00, GST $180.00 (9%), baseline nett $1,180.00
--     (SG/PR 21+, 50%), MCES/SME nett $780.00 (SG 40+, 70%).
--   * Course information: 4 days / 32 hrs, Intermediate, 2 hrs assessment.
--   * Funding validity 4 Mar 2024 - 3 Mar 2028; Absentee Payroll $4.50/hr.
--   * Skills Framework: Solution Architecture (ICT-DES-4006-1.1).
--   * Exam weightings from the official study guide, skills measured as of 27 Jul 2026.
--   * No exam-specific practice-exam URL exists, so the post links only the portal root
--     (never a deep link that 404s).
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'AZ-400 DevOps Engineer Expert in Singapore: Exam Domains, Funding and Practice Exams', 'az-400-devops-engineer-expert-singapore-guide', 'AZ-400 is the Microsoft credential for engineers who own CI/CD, release management and platform reliability. This guide walks the exam domains and their weightings, sets out exactly what you pay after WSQ funding &mdash; $1,180 nett, or $780 for Singapore Citizens aged 40 and above &mdash; and shows what the 4 days course covers.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>AZ-400</strong> is the Microsoft credential for engineers who own CI/CD, release management and platform reliability. This guide covers what the exam measures, what the 4 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$1,180</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$780</strong> for Singapore Citizens aged 40 and above.</p></div><h2>Why AZ-400 is worth sitting</h2><p>AZ-400 is an expert-level certification, and the exam is unusually lopsided: designing and implementing build and release pipelines is worth 50&ndash;55% on its own. That single fact should shape how you prepare &mdash; everything else on the syllabus matters, but pipelines are the exam.</p><ul><li><strong>Build and release pipelines carry 50&ndash;55% of the marks</strong> &mdash; over half the exam sits in one domain.</li><li><strong>It is an expert-level certification</strong> and requires AZ-104 or AZ-204 first.</li><li><strong>Both Azure DevOps and GitHub are covered</strong>, including GitHub Actions, which reflects how teams actually work.</li><li><strong>Secure DevOps is included</strong> &mdash; dependency scanning, static and dynamic analysis, and compliance.</li></ul><p>The course is mapped to the Skills Framework under <strong>Solution Architecture</strong> (TSC code ICT-DES-4006-1.1), and leads to roles such as Data Scientist, Machine Learning Engineer, AI Researcher, Deep Learning Specialist. <a href="https://www.tertiarycourses.com.sg/wsq-designing-and-implementing-microsoft-devops-solutions-az-400.html">Check the funding you qualify for</a>.</p><h2>The AZ-400 exam at a glance</h2><table><tbody><tr><td>Exam</td><td>AZ-400: Designing and Implementing Microsoft DevOps Solutions</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled &mdash; not 70%)</td></tr><tr><td>Certification</td><td>DevOps Engineer Expert</td></tr><tr><td>Prerequisite</td><td>AZ-104 or AZ-204 must be held first</td></tr><tr><td>Renewal</td><td>Free online renewal every 12 months</td></tr></tbody></table><h2>AZ-400 exam domains and weightings</h2><p>One domain dominates this exam: build and release pipelines account for over half the marks, so that is where your revision time belongs.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Configure processes and communications</td><td>10&ndash;15%</td></tr><tr><td>Design and implement a source control strategy</td><td>10&ndash;15%</td></tr><tr><td>Design and implement build and release pipelines</td><td>50&ndash;55%</td></tr><tr><td>Develop a security and compliance plan</td><td>10&ndash;15%</td></tr><tr><td>Implement an instrumentation strategy</td><td>5&ndash;10%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of 27 Jul 2026.</em></p><h2>What the WSQ course covers</h2><p>The 4 days (32 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-designing-and-implementing-microsoft-devops-solutions-az-400.html"><strong>WSQ - Designing and Implementing Microsoft DevOps Solutions (AZ-400)</strong></a> course is pitched at <strong>Intermediate</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>Introduction to DevOps</li><li>Choose the right project</li><li>Describe team structures</li><li>Choose the DevOps tools</li><li>Plan Agile with GitHub Projects and Azure Boards</li><li>Introduction to source control</li><li>Describe types of source control systems</li><li>Work with Azure Repos and GitHub</li><li>Structure your Git Repo</li><li>Manage Git branches and workflows</li><li>Collaborate with pull requests in Azure Repos</li><li>Identify technical debt</li><li>Explore Git hooks</li><li>Plan foster inner source</li></ol><p>The full outline runs to 57 topics &mdash; see the <a href="https://www.tertiarycourses.com.sg/wsq-designing-and-implementing-microsoft-devops-solutions-az-400.html">course page</a> for the complete list.</p><h2>Practise before you book the exam</h2><p>Course participants get access to our <a href="https://exams.tertiaryinfotech.com/practice-exams">Practice Exam Portal</a>, which carries timed mock papers across the Microsoft certification track. Rehearsing under exam conditions is the single best predictor of a first-time pass.</p><h2>What you actually pay: funding for AZ-400 training</h2><p>The full fee is $2,000 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$2,180</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$1,180</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$780</strong></td></tr></tbody></table><p><em>GST of $180 is charged at 9% on the full course fee of $2,000, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><p>Funding for this course is valid from <strong>4 Mar 2024</strong> to <strong>3 Mar 2028</strong>. You must register and complete the course within that window to qualify.</p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-designing-and-implementing-microsoft-devops-solutions-az-400.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>Your route to certification</h2><ol><li><strong>Register for the 4 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-designing-and-implementing-microsoft-devops-solutions-az-400.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li><li><strong>Book and sit AZ-400</strong> through Pearson VUE. The certification exam is booked and paid for separately from the course.</li></ol><h2>Where to go after AZ-400</h2><p>AZ-305 covers Azure solutions architecture if you are moving towards design authority. On the source-control and automation side, <a href="https://www.tertiarycourses.com.sg/wsq-github-foundations-certification-training.html">GitHub Foundations</a> is a useful complement for teams standardising on GitHub. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need another certification before AZ-400?</summary><div class="mmd-faq-a"><p>Yes. Microsoft requires you to hold either AZ-104 (Azure Administrator Associate) or AZ-204 (Azure Developer Associate) before the DevOps Engineer Expert certification is awarded.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Which part of the exam should I focus on?</summary><div class="mmd-faq-a"><p>Build and release pipelines, without question &mdash; that domain alone is 50&ndash;55% of the exam. The other four domains together account for the rest.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Does the course cover GitHub as well as Azure DevOps?</summary><div class="mmd-faq-a"><p>Yes. GitHub Actions, GitHub Projects and GitHub Packages are covered alongside Azure Pipelines, Repos and Boards.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the exam fee included?</summary><div class="mmd-faq-a"><p>No. The course fee covers training and the WSQ assessment. The AZ-400 exam is booked separately through Pearson VUE.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">How long is the course?</summary><div class="mmd-faq-a"><p>4 days (32 hours), followed by a 2-hour assessment.</p></div></details></div><h2>Register for DevOps Engineer Expert training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-designing-and-implementing-microsoft-devops-solutions-az-400.html"><strong>WSQ - Designing and Implementing Microsoft DevOps Solutions (AZ-400)</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-10-14', 'TGS-2024042605', 'TGS-2024042605', 'AZ-400 Course Singapore | DevOps Engineer Expert | WSQ Funding', 'Train for AZ-400 DevOps Engineer Expert in Singapore. 4 days WSQ course from $780 nett after funding, full exam domain breakdown.', 'az-400 course singapore, devops engineer expert certification, az-400 exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, az-400 funding, az-400 training singapore', 'manual-skip-no-share', '2025-10-14 09:00:00', '2025-10-14 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'az-400-devops-engineer-expert-singapore-guide');

