INSERT INTO `tag` (`name`, `status`) SELECT 'Azure', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Azure') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'AZ-400', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'AZ-400') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'DevOps', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'DevOps') x);
